-- A05 PLACES_SQL {}
EXPLAIN (ANALYZE, BUFFERS) WITH hashes AS ( SELECT DISTINCT hv.method_hash FROM cpc_curve_verdicts hv WHERE hv.method_version = 'cpc_curves_v1' ), inforce AS ( SELECT h.method_hash, l.backtest_version FROM hashes h CROSS JOIN LATERAL ( SELECT lv.backtest_version FROM cpc_curve_verdicts lv WHERE lv.method_hash = h.method_hash AND lv.method_version = 'cpc_curves_v1' ORDER BY lv.scored_at DESC, lv.backtest_version DESC LIMIT 1) l ) SELECT v.backtest_version, v.scored_at, v.truth_frontier, v.method_version, v.method_hash, v.rules_version, v.rules_hash, v.min_n_eff, v.product, v.place_kind, v.place, v.weighting, v.season, v.strength, v.n, v.n_eff, v.skill, v.t, v.strength_verdict, v.share_p5_p95, v.share_p25_p75, v.season_n, v.season_n_eff, v.season_skill, v.season_t, v.verdict, v.history_years_in_base, v.band_basis, v.band_basis_n, v.band_basis_n_eff, v.band_share, v.band_claim, v.band_sentence, v.drawable FROM cpc_curve_verdicts v JOIN inforce i ON i.method_hash = v.method_hash AND i.backtest_version = v.backtest_version WHERE v.method_version = 'cpc_curves_v1' ORDER BY v.place_kind, v.place, v.weighting, v.product, v.season, v.strength;

-- B05 PLACES_SQL {}
EXPLAIN (ANALYZE, BUFFERS) WITH hashes AS ( SELECT DISTINCT method_hash FROM cpc_curve_verdicts ), inforce AS ( SELECT h.method_hash, l.backtest_version FROM hashes h CROSS JOIN LATERAL ( SELECT backtest_version FROM cpc_curve_verdicts v WHERE v.method_hash = h.method_hash ORDER BY scored_at DESC, backtest_version DESC LIMIT 1) l ) SELECT v.backtest_version, v.scored_at, v.truth_frontier, v.method_version, v.method_hash, v.rules_version, v.rules_hash, v.min_n_eff, v.product, v.place_kind, v.place, v.weighting, v.season, v.strength, v.n, v.n_eff, v.skill, v.t, v.strength_verdict, v.share_p5_p95, v.share_p25_p75, v.season_n, v.season_n_eff, v.season_skill, v.season_t, v.verdict, v.history_years_in_base, v.band_basis, v.band_basis_n, v.band_basis_n_eff, v.band_share, v.band_claim, v.band_sentence, v.drawable FROM cpc_curve_verdicts v JOIN inforce i ON i.method_hash = v.method_hash AND i.backtest_version = v.backtest_version ORDER BY v.place_kind, v.place, v.weighting, v.product, v.season, v.strength;

