EXPLAIN (ANALYZE, BUFFERS) WITH p AS ( SELECT unnest(ARRAY['610temp','814temp']::text[]) AS product ), iss AS ( SELECT p.product, l.issued_date FROM p CROSS JOIN LATERAL ( SELECT issued_date FROM cpc_outlook_curves c WHERE c.product = p.product ORDER BY issued_date DESC LIMIT 1) l ) SELECT c.product, c.issued_date, c.valid_start, c.valid_end, c.place_kind, c.place, c.weighting, c.season, c.strength, c.method_version FROM iss JOIN cpc_outlook_curves c ON c.product = iss.product AND c.issued_date = iss.issued_date AND c.day_index IS NULL ORDER BY c.product, c.place_kind, c.place, c.weighting;
